from ielts_h import rstory
READ3 = [rstory("A Walking School Bus", "True / False / Not Given",
 "In a small town in Wales, parents have started a walking school bus. A group of children walk to school together each morning, led by two adults who take turns. The children meet at set points along the route and join the group as it passes. The scheme began in 2019 with eight children and now includes forty. Parents say the children are fitter and arrive at school more awake. However, the scheme does not run on rainy days, when most families drive instead.",
 "Di sebuah kota kecil di Wales, para orang tua memulai bus sekolah jalan kaki. Sekelompok anak berjalan bersama ke sekolah setiap pagi, dipimpin dua orang dewasa yang bergiliran. Anak-anak bertemu di titik-titik tertentu sepanjang rute dan bergabung dengan rombongan saat lewat. Program ini dimulai tahun 2019 dengan delapan anak dan kini mencakup empat puluh. Orang tua mengatakan anak-anak lebih bugar dan tiba di sekolah dengan lebih segar. Namun, program ini tidak berjalan pada hari hujan, ketika sebagian besar keluarga memilih mengemudi.",
 [("Apa gagasan utama teks?", "anak-anak berjalan ke sekolah secara berkelompok", "mobil adalah cara terbaik ke sekolah", "sekolah baru dibuka di Wales", "olahraga wajib untuk semua anak", "Gagasan utama.")],
 [("The walking school bus started in 2019.", 'T', "Teks: began in 2019."),
  ("Two adults lead the group.", 'T', "Teks: led by two adults."),
  ("The group now includes eight children.", 'F', "Teks: now includes forty."),
  ("The scheme runs on rainy days.", 'F', "Teks: does not run on rainy days."),
  ("The scheme is paid for by the town council.", 'N', "Pembiayaan tidak disebut.")],
 [("Program ini dimulai dengan delapan anak.", "The scheme began with ___ children.", "eight", "Teks: eight children."),
  ("Anak-anak bertemu di titik-titik tertentu.", "They meet at set ___ along the route.", "points", "Teks: set points.")])]
